# 54 best logos of all time: (slug, name, url, verified fact, observation 1, observation 2, slide notes)
# The 18 logos from the original article keep their original explanations as observations.
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
# Wordmarks
("coca-cola","Coca-Cola","https://www.coca-cola.com/","Frank Mason Robinson, the company's bookkeeper, wrote the Coca-Cola name in Spencerian script in 1886.","The quintessential wordmark: the script logo has remained largely unchanged for decades.","Its flowing letters have become synonymous with refreshment and American culture."),
("sony","Sony","https://www.sony.com/","Sony was founded in Tokyo in 1946 and adopted the Sony name in 1958.","A clean, bold slab serif makes the short name feel solid and precise.","The minimalist approach reflects the company's dedication to technological precision."),
("google","Google","https://www.google.com/","Google switched to its current sans serif logo in 2015.","Playful, multi-coloured letters show how a simple wordmark can have personality and still look professional.","The green l breaks the colour pattern, a small surprise that makes the logo memorable."),
("fedex","FedEx","https://www.fedex.com/","Lindon Leader at Landor designed the FedEx logo in 1994, with an arrow hidden between the E and the x.","Purple and orange split the name into Fed and Ex.","Once you see the white arrow in the negative space, you can't unsee it."),
("disney","Disney","https://www.disney.com/","The Walt Disney Company was founded in 1923, and its script logo is based on Walt Disney's stylised signature.","The curly D and looping letters feel personal and magical.","A signature-style logo makes a huge company feel like it was made by one storyteller."),
("netflix","Netflix","https://www.netflix.com/","Netflix introduced its current wordmark in 2014.","Tall, condensed red capitals look like a cinema marquee.","The letters sit on a slight curve, like a curved cinema screen."),
("supreme","Supreme","https://www.supremenewyork.com/","Supreme opened its first store in New York in 1994.","White italic letters sit inside a solid red box.","The box logo is so simple that it works as a sticker, a label and a status symbol."),
("visa","Visa","https://www.visa.com/","Visa updated its wordmark in 2021 with a flat, single-blue version.","Heavy blue italic capitals lean forward, suggesting speed.","The short name is easy to read on a card, a terminal and a phone screen."),
("kelloggs","Kellogg's","https://www.kelloggs.com/","Will Keith Kellogg founded the company in Battle Creek, Michigan, in 1906, and the script logo grew out of his signature.","A red script with a tall K feels warm and familiar.","The handwritten style makes a giant food company feel personal, like a family recipe."),
# Monograms
("ibm","IBM","https://www.ibm.com/","Paul Rand designed the eight-bar IBM logo in 1972.","The striped logo turned \"International Business Machines\" into one of the most recognisable corporate symbols.","Its horizontal stripes suggest speed and dynamism."),
("louis-vuitton","Louis Vuitton","https://www.louisvuitton.com/","Georges Vuitton created the LV Monogram canvas in 1896.","The interlocked letters show how a monogram can become a valuable brand asset.","Printed across bags and trunks, the LV works as both logo and pattern."),
("h-and-m","H&M","https://www.hm.com/","H&M opened in Västerås, Sweden, in 1947 as Hennes, and the name now stands for Hennes & Mauritz.","Proving that simplicity works, the red monogram is recognised around the world.","Few people know what the letters stand for, which shows how a monogram can replace a name."),
("chanel","Chanel","https://www.chanel.com/","Gabrielle 'Coco' Chanel founded the house in Paris, and the interlocking Cs are her initials.","Two Cs face away from each other and lock together in a perfectly balanced shape.","Wide geometric capitals below the mark keep the full name simple and modern."),
("hp","HP","https://www.hp.com/","Bill Hewlett and David Packard founded HP in a Palo Alto garage in 1939.","White italic letters sit inside a blue circle.","The two lowercase letters turn the founders' names into a compact badge."),
("cnn","CNN","https://www.cnn.com/","CNN launched in Atlanta in 1980 as the first 24-hour television news channel.","The three letters are drawn as one continuous line, like a cable.","Red outlined letters make the logo instantly recognisable on screen."),
("ge","GE","https://www.ge.com/","General Electric was founded in 1892, and its script monogram has been used for more than a century.","Flowing script letters G and E sit inside a round badge.","The decorative swirls around the circle make the monogram feel classic and engineered at once."),
("volkswagen","Volkswagen","https://www.vw.com/","Volkswagen introduced its flat, two-dimensional logo in 2019.","A V sits above a W inside a circle, joined by thin lines.","The flat redesign made the logo work better on screens and in animation."),
("mcdonalds","McDonald's","https://www.mcdonalds.com/","The Golden Arches became McDonald's logo in 1968, inspired by the arches on its early restaurants.","Two golden arches form a single M.","The yellow M is so famous that it works without the name, even from far away on a highway."),
# Pictorial marks
("apple","Apple","https://www.apple.com/","Rob Janoff designed the bitten Apple logo in 1977.","The bitten apple silhouette is perhaps the most famous pictorial mark in technology.","It represents knowledge, innovation and simplicity, and the bite keeps it from looking like a cherry."),
("twitter","Twitter","https://x.com/","Twitter used this bird from 2012 until it rebranded as X in 2023.","The Twitter bird became synonymous with social media communication.","It shows how a simple animal symbol can represent complex technology."),
("shell","Shell","https://www.shell.com/","Raymond Loewy redesigned the Shell pecten in 1971.","The shell symbol has evolved from a realistic drawing to today's bold, simplified shape.","It shows how pictorial marks can modernise while keeping recognition."),
("target","Target","https://www.target.com/","The first Target store opened in Roseville, Minnesota, in 1962.","A red bullseye turns the name into a picture.","The symbol is so simple that the company often uses it without the name."),
("wwf","WWF","https://www.worldwildlife.org/","WWF's panda logo, first drawn in 1961, was inspired by Chi Chi, a giant panda at London Zoo.","Black shapes on white suggest the panda without drawing every line.","The animal tells you what the organisation protects, and it works in one colour."),
("lacoste","Lacoste","https://www.lacoste.com/","Tennis player René Lacoste co-founded the brand in 1933; his nickname was the Crocodile.","A green crocodile sits beside thin serif capitals.","The crocodile is famous on its own as the small badge on a polo shirt."),
("puma","Puma","https://www.puma.com/","Rudolf Dassler founded Puma in Herzogenaurach, Germany, in 1948.","A leaping cat jumps over heavy capitals.","The animal suggests speed and power, which suits a sports brand."),
("penguin-books","Penguin Books","https://www.penguin.co.uk/","Allen Lane founded Penguin Books in London in 1935, and Edward Young drew the first penguin.","A simple penguin sits inside an orange oval.","The friendly bird made cheap paperbacks look trustworthy and fun."),
("instagram","Instagram","https://www.instagram.com/","Instagram replaced its brown camera icon with a gradient glyph in 2016.","A simple outline of a camera sits on a warm gradient.","The glyph is built for an app icon, so it reads at a tiny size."),
# Abstract marks
("nike","Nike","https://www.nike.com/","Carolyn Davidson designed the Swoosh in 1971 as a design student.","Originally representing speed and movement, the swoosh has become a symbol of athletic achievement.","A single curve works on shoes, shirts and billboards without the name."),
("chase","Chase","https://www.chase.com/","Chermayeff & Geismar designed the Chase octagon in 1961.","One of the earliest abstract corporate logos, the octagon proved that non-representational designs can be timeless.","Four rotated pieces form a square inside an octagon, a shape that suggests security."),
("mitsubishi","Mitsubishi","https://www.mitsubishi.com/","The three diamonds combine the Iwasaki family crest with the crest of the Tosa clan, linked to founder Yataro Iwasaki.","Three red diamonds meet at a single point.","The mark works across very different businesses, from cars to heavy industry."),
("pepsi","Pepsi","https://www.pepsi.com/","Pepsi unveiled its current logo in 2023, bringing back the bold black wordmark inside the globe.","A red, white and blue globe is split by a wavy white band.","Putting the name back inside the globe makes the logo bolder on cans and screens."),
("mercedes-benz","Mercedes-Benz","https://www.mercedes-benz.com/","Daimler registered the three-pointed star in 1909 as a symbol of engines on land, at sea and in the air.","A three-pointed star sits inside a thin ring.","The simple, symmetrical shape works as a badge on the front of every car."),
("adidas","Adidas","https://www.adidas.com/","Adi Dassler registered Adidas in 1949 in Herzogenaurach, Germany.","Three slanted bars form a shape like a mountain.","The bars echo the three stripes that have been on Adidas shoes for decades."),
("airbnb","Airbnb","https://www.airbnb.com/","Airbnb introduced the Bélo symbol in 2014.","One continuous line forms a shape that suggests a heart, a location pin and the letter A.","Coral colour and rounded letters make the brand feel warm and welcoming."),
("spotify","Spotify","https://www.spotify.com/","Spotify was founded in Stockholm in 2006.","Three curved lines inside a circle suggest sound waves.","The bright green is one of the most recognisable colours in tech."),
("mastercard","Mastercard","https://www.mastercard.com/","Pentagram redesigned the Mastercard logo in 2016, and since 2019 the circles can appear without the name.","Two overlapping circles in red and yellow create an orange overlap.","The mark is so recognisable that it works without any words."),
# Mascot logos
("kfc","KFC","https://www.kfc.com/","Harland Sanders sold the first Kentucky Fried Chicken franchise in 1952, and his portrait has been part of the logo for decades.","Colonel Sanders' portrait has become a global symbol of the brand.","It proves that a founder's image can evolve into a powerful brand mascot."),
("michelin","Michelin","https://www.michelin.com/","Bibendum, the Michelin Man, first appeared in 1898.","The Michelin Man shows how even industrial products can be humanised.","His body is made of stacked tyres, so the mascot explains the product."),
("pringles","Pringles","https://www.pringles.com/","Pringles redrew its mascot Mr. P in 2021 with a simpler, flatter look.","Mr. P, the moustached face, makes the brand approachable and memorable.","The face sits right on the can, so the mascot is the packaging."),
("mailchimp","Mailchimp","https://mailchimp.com/","Mailchimp was founded in Atlanta in 2001 and bought by Intuit in 2021.","Freddie the chimp winks from inside the logo.","A friendly mascot makes a marketing software brand feel human and playful."),
("reddit","Reddit","https://www.reddit.com/","Reddit was founded in 2005, and its alien mascot is called Snoo.","A white alien head sits inside an orange-red circle.","The simple mascot works as the app icon and appears in countless fan versions."),
("duolingo","Duolingo","https://www.duolingo.com/","Duolingo was founded in Pittsburgh in 2011, and its owl mascot is called Duo.","A round green owl with big eyes is the face of the app.","Duo has become famous through memes, which shows how a mascot can build a brand."),
("wendys","Wendy's","https://www.wendys.com/","Dave Thomas opened the first Wendy's in Columbus, Ohio, in 1969 and named it after his daughter.","A friendly portrait of a red-haired girl sits above the name.","The red script name is set in a casual, hand-drawn style."),
("planters","Planters","https://www.planters.com/","Mr. Peanut was created in 1916 from a schoolboy's drawing.","Mr. Peanut, with his top hat and monocle, stands beside the name.","The blue banner and yellow letters make the logo stand out on the shelf."),
("bic","BIC","https://www.bicworld.com/","The BIC Boy, drawn by Raymond Savignac, joined the logo in 1961.","A small figure with a ball head stands beside an orange shape with the name.","The ball head is a nod to the ball of a BIC pen."),
# Emblems
("starbucks","Starbucks","https://www.starbucks.com/","Starbucks dropped its name from the logo in 2011, leaving the green siren on its own.","The twin-tailed siren in a circular frame combines mythology with modern design.","It works without words, which helped the brand grow beyond coffee."),
("harley-davidson","Harley-Davidson","https://www.harley-davidson.com/","Harley-Davidson was founded in Milwaukee in 1903.","The bar and shield emblem represents heritage and authority in motorcycle culture.","Orange and black make the badge bold enough for tattoos, tanks and jackets."),
("bmw","BMW","https://www.bmw.com/","BMW introduced a flat, transparent version of its roundel in 2020; the blue and white come from the colours of Bavaria.","The circular emblem shows how company history can be preserved in a logo.","The letters BMW sit on the outer ring around the blue and white quarters."),
("porsche","Porsche","https://www.porsche.com/","The Porsche crest, introduced in 1952, combines the horse of Stuttgart with the colours and antlers of Württemberg.","A black horse sits in the centre of a gold shield.","Red stripes and antlers around it tell the story of the company's home region."),
("ford","Ford","https://www.ford.com/","Ford Motor Company was founded in 1903.","A white script name sits inside a blue oval.","The script feels personal and traditional, like a signature on a classic car."),
("warner-bros","Warner Bros.","https://www.warnerbros.com/","Warner Bros. was founded in 1923 by four brothers.","The WB letters sit inside a shield.","The shield has been redrawn many times, but its shape is instantly recognisable on film."),
("burger-king","Burger King","https://www.bk.com/","Burger King's 2021 rebrand brought back a bun-shaped logo close to the one it used from 1969 to 1999.","The name is sandwiched between two halves of a bun.","Round, chunky letters make the logo look as tasty as the food."),
("stella-artois","Stella Artois","https://www.stellaartois.com/","Stella Artois traces its brewing history to the Den Hoorn brewery in Leuven, founded in 1366.","An ornate emblem with a red banner looks like an old beer label.","The heritage details signal tradition and quality."),
("lamborghini","Lamborghini","https://www.lamborghini.com/","Ferruccio Lamborghini founded the car maker in 1963; the bull reflects his zodiac sign, Taurus.","A charging bull sits inside a gold-edged black shield.","The bull suggests power and aggression, which suits supercars."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 54
